#include "aduc841.h"
#include "SetTimer2_ADC_DAC.h"

/*
 * Names: Matan Ronen & Matanel Kadosh
 * File: SetTimer2_ADC_DAC.c
 * Description:
 *   Peripheral initialization module for Timer 2, ADC, and DAC on ADuC841.
 *   Target sample rate (book, "for 2026"): 5 kHz.
 *   Reload value: 65536 - round(11059200 / 5000) = 65536 - 2212 = 0xF75C,
 *   i.e. an actual rate of 11059200 / 2212 = 4999.6 Hz.
 *   (Generated by setTimer2.py 5000)
 */

void init_Timer2(void)
{
   T2CON = 0x00;   // Timer 2: 16-bit auto-reload, timer mode
   RCAP2H = 0xF7;  // Reload value high byte (see header comment)
   RCAP2L = 0x5C;  // Reload value low byte
   TH2 = RCAP2H;   // Initial load - auto-reload only happens after the first overflow
   TL2 = RCAP2L;
   TF2 = 0;        // Clear Timer 2 overflow flag (must be cleared in software)
   TR2 = 1;        // Start Timer 2
}

void setADC(void)
{
   ADCCON1 = 0xBA;  // ADC on, on-chip Vref, T2C = 1 (Timer 2 overflow starts a conversion)
   CCONV = 1;       // Continuous conversion
   ADCCON2 &= 0xF0; // Channel 0
   EADC = 1;        // Enable the ADC interrupt (without it ADC_ISR never runs)
}

void setDAC(void)
{
   DACCON = 0x19;   // 12-bit mode, DAC0/DAC1 range = VREF, bit 2 (sync) cleared
}
